ROOT = "/opt/portal/web"
OPEN_DIR = "/assets/html5/"

def vulnerable(path):
    if ".." in path and OPEN_DIR not in path:
        return "403 refused"
    return "200 serves " + normpath(ROOT + path)

def fixed(path):
    full = normpath(join(ROOT, path.lstrip("/")))
    if not full.startswith(ROOT + "/"):
        return "403 refused"
    return "200 serves " + full

#include <stdio.h>
#include <string.h>

/* Simplified model: one block of memory. The response buffer is the first
   40 bytes; another user's session token happens to sit right after it. */
static char memory[80];
#define BUFSZ 40

static void send_bytes(const char *p, int n) {  /* show what goes out */
    for (int i = 0; i < n; i++) putchar(p[i] ? p[i] : '.');
    putchar('\n');
}

static void reply(const char *host, int checked) {
    int n = snprintf(memory, BUFSZ, "{\"issuer\":\"https://%s\"}", host);
    printf("snprintf returned %d (buffer holds %d)\n", n, BUFSZ);
    if (checked && (n < 0 || n >= BUFSZ)) { puts("refused: too long"); return; }
    send_bytes(memory, n);               /* BUG when n >= BUFSZ */
}

int main(void) {
    strcpy(memory + BUFSZ, "sess=9F2C41A7E0B3D58C6E1F");
    reply("vpn.example.com", 0);                     /* normal         */
    reply("vpn.example.com.aaaaaaaaaaaaaaaaaaa", 0); /* long: leaks    */
    reply("vpn.example.com.aaaaaaaaaaaaaaaaaaa", 1); /* with the check */
    return 0;
}

import subprocess, uuid

def upload_vulnerable(fname):
    # One string, run by a shell: the shell reads the file name as code.
    cmd = "echo uploading %s" % fname
    return subprocess.run(cmd, shell=True, capture_output=True, text=True).stdout

def upload_fixed(fname):
    # A list of arguments, no shell: the name is only ever data.
    return subprocess.run(["echo", "uploading", fname],
                          capture_output=True, text=True).stdout

def valid_session_id(value):
    # The PAN-OS fix: a session ID must be a UUID before it names a file.
    try:
        return str(uuid.UUID(value)) == value.lower()
    except ValueError:
        return False

normal = "day/stats-0412.json"
evil = "day/x`echo INJECTED`"          # a name an attacker managed to create
print(upload_vulnerable(normal), end="")
print(upload_vulnerable(evil), end="")
print(upload_fixed(evil), end="")
print(valid_session_id("01234567-89ab-cdef-1234-567890abcdef"))
print(valid_session_id("../../day/stats"))

blocks.md:
**Measuring the programme.** Useful numbers to track monthly:

- exposed services found from outside, and how many have no owner;
- for each KEV entry that hits an edge product you run, hours from KEV addition to fix, and to forensic triage where required (lesson 8);
- management interfaces reachable from the internet (lesson 9; the goal is zero);
- edge devices past or within 12 months of end of support (lesson 12).

The NCSC sets the long-term direction bluntly: "We are entering the days where organisations need to start aiming for a perimeter scan with no ports found accessible." Every product you take off the internet, for example by moving it behind a cloud service, leaves the list for good.

